import{_ as t,c as s,o as a,ah as r,j as e,a as n}from"./chunks/framework.oAolcYhj.js";const d="/Qonnectra-docs/pr-14/images/manual/teil-a/conduit_connection.jpg",o="/Qonnectra-docs/pr-14/images/manual/teil-a/conduit_connection_edit_area.jpg",u="/Qonnectra-docs/pr-14/images/manual/teil-a/conduit_connection_conduit.jpg",h="/Qonnectra-docs/pr-14/videos/conduit_connection_map_selection.webm",l="/Qonnectra-docs/pr-14/images/manual/teil-a/conduit_connection_list.jpg",c="/Qonnectra-docs/pr-14/videos/conduit_connection_map_find.webm",g="/Qonnectra-docs/pr-14/images/manual/teil-a/conduit_connection_routing.jpg",m="/Qonnectra-docs/pr-14/videos/conduit_connection_routing.webm",b="/Qonnectra-docs/pr-14/images/manual/teil-a/conduit_connection_linked_trenches.jpg",p="/Qonnectra-docs/pr-14/images/manual/teil-a/conduit_connection_project_flag.jpg",v=JSON.parse('{"title":"11. Rohrzuordnung","description":"","frontmatter":{},"headers":[],"relativePath":"manual/teil-a-anwenderhandbuch/11-rohrzuordnung.md","filePath":"manual/teil-a-anwenderhandbuch/11-rohrzuordnung.md"}'),_={name:"manual/teil-a-anwenderhandbuch/11-rohrzuordnung.md"};function z(f,i,k,w,T,R){return a(),s("div",null,[...i[0]||(i[0]=[r('<h1 id="_11-rohrzuordnung" tabindex="-1">11. Rohrzuordnung <a class="header-anchor" href="#_11-rohrzuordnung" aria-label="Permalink to &quot;11. Rohrzuordnung&quot;">​</a></h1><p>Die <strong>Rohrzuordnung</strong> ordnet Rohre den <strong>Trassensegmenten</strong> zu, in denen sie liegen. Sie erreichen sie über die linke Navigation in der Gruppe „Rohr“ durch Klicken auf den Menüpunkt „Zuordnung“.</p><p><img src="'+d+'" alt="Screenshot Rohrzuordnung mit der Karte links und dem Arbeitsbereich rechts" data-zoomable="true"></p><p>Der Bildschirm ist zweigeteilt: links die Karte, rechts der Arbeitsbereich. Die Zuordnung geschieht in der Karte: Sie wählen rechts ein Rohr aus und klicken links das Trassensegment an, in dem es liegt. Ein <strong>Trassensegment</strong> ist ein einzelnes Objekt des Layers „Trasse“ und trägt eine eigene Trassen-ID.</p><p>Anklickbar sind ausschließlich die Segmente dieses Layers. Adressen, Netzknoten und Gebiete zeichnet die Karte zwar mit, sie dienen hier aber nur der Orientierung – eine Info-Box wie in der Karte (siehe Kapitel <a href="./05-karte.html">Karte</a>) öffnet sich nicht.</p><p>Solange kein Rohr ausgewählt ist, bleiben Klicks in die Karte ohne Wirkung; ein Hinweis am unteren Rand der Karte fordert zur Auswahl auf. Klicken Sie trotzdem hinein, erscheint die Meldung „Kein Rohr ausgewählt“.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Es gibt keinen „Speichern“-Button. Jede Zuordnung ist mit dem Klick gespeichert und lässt sich nur durch Löschen wieder aufheben, siehe Abschnitt <a href="#_11-2-3-zuordnung-loschen">Zuordnung löschen</a>.</p></div><p>Die Karte verhält sich wie in Abschnitt <a href="./03-wiederkehrende-bedienelemente.html#_3-3-das-kartenfenster">Das Kartenfenster</a> beschrieben.</p><h2 id="_11-1-rohr-auswahlen" tabindex="-1">11.1 Rohr auswählen <a class="header-anchor" href="#_11-1-rohr-auswahlen" aria-label="Permalink to &quot;11.1 Rohr auswählen&quot;">​</a></h2><p>Rechts neben der Karte liegt der Arbeitsbereich, von oben nach unten: die Umschalter „Routing-Modus“ und „Trassenverbindungen anzeigen“, die Felder „Kennzeichen“ und „Rohr“ und darunter die Liste der zugeordneten Trassensegmente.</p><p><img src="'+o+'" alt="Screenshot Rohrzuordnung mit Hervorhebung des Arbeitsbereichs rechts neben der Karte" data-zoomable="true"></p><p>Zur Auswahl stehen die Rohre des Projekts, das oben links in der Kopfzeile ausgewählt ist – eingegrenzt auf das Kennzeichen im gleichnamigen Feld, siehe Abschnitt <a href="#_11-6-nach-kennzeichen-eingrenzen">Nach Kennzeichen eingrenzen</a>.</p><p>Die Rohre stehen in der Liste mit ihrem Rohrtyp in Klammern, etwa „St-VL-02 (7x16/12)“ – anders als in der Rohrverwaltung, die Name und Rohrtyp in getrennten Spalten führt.</p><p><img src="'+u+'" alt="Screenshot Rohrzuordnung mit Hervorhebung des Feldes „Rohr“ und der geöffneten Rohrliste im Arbeitsbereich" data-zoomable="true"></p><p>Mit der Auswahl füllt sich die Liste darunter mit den Trassensegmenten, die dem Rohr bereits zugeordnet sind.</p><h2 id="_11-2-trassen-einzeln-zuordnen-und-zuordnung-aufheben" tabindex="-1">11.2 Trassen einzeln zuordnen und Zuordnung aufheben <a class="header-anchor" href="#_11-2-trassen-einzeln-zuordnen-und-zuordnung-aufheben" aria-label="Permalink to &quot;11.2 Trassen einzeln zuordnen und Zuordnung aufheben&quot;">​</a></h2><h3 id="_11-2-1-trassensegmente-zuordnen" tabindex="-1">11.2.1 Trassensegmente zuordnen <a class="header-anchor" href="#_11-2-1-trassensegmente-zuordnen" aria-label="Permalink to &quot;11.2.1 Trassensegmente zuordnen&quot;">​</a></h3><p>Klicken Sie in der Karte auf das Trassensegment, in dem das ausgewählte Rohr liegt. Achten Sie darauf, dass der Layer „Trasse“ in der Legende eingeschaltet ist und dass der Routing-Modus so steht, wie Sie ihn brauchen, siehe Abschnitt <a href="#_11-3-routing-modus">Routing-Modus</a>.</p><p>Nach der Zuordnung erscheint kurz die Meldung „Trassenverbindung gespeichert“, und das Segment steht in der Liste.</p>',19),e("p",null,[e("video",{src:h,controls:"",playsinline:"",preload:"metadata"},[n(" Ihr Browser unterstützt das Abspielen von HTML5-Videos nicht. Sie können die Datei "),e("a",{href:"/videos/conduit_connection_map_selection.webm",download:""},"herunterladen"),n(" anstelle des Videos. ")])],-1),r('<div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Ein Trassensegment kann mehrere Rohre führen; dasselbe Segment taucht deshalb bei mehreren Rohren in der Liste auf. Klicken Sie ein Segment an, das dem Rohr schon zugeordnet ist, meldet Qonnectra „Keine neuen Trassenverbindungen“ und ändert nichts.</p></div><h3 id="_11-2-2-zugeordnete-trassensegmente-finden" tabindex="-1">11.2.2 Zugeordnete Trassensegmente finden <a class="header-anchor" href="#_11-2-2-zugeordnete-trassensegmente-finden" aria-label="Permalink to &quot;11.2.2 Zugeordnete Trassensegmente finden&quot;">​</a></h3><p>Die Liste führt die Trassen-IDs der zugeordneten Segmente auf. Ein Klick auf die Spaltenüberschrift „Trassen-ID“ kehrt die Sortierung um, das Suchfeld darüber grenzt die Liste ein; beides bezieht sich auf alle Einträge, nicht nur auf die angezeigte Seite. Eine Seite umfasst zehn Einträge; darunter stehen die Gesamtzahl und die Seitenauswahl.</p><p><img src="'+l+'" alt="Screenshot Rohrzuordnung mit Hervorhebung der Liste der zugeordneten Trassensegmente samt Suchfeld und Seitenauswahl im Arbeitsbereich" data-zoomable="true"></p><p>Ein Klick auf eine Zeile zoomt die Karte auf das Segment und hebt es kurz blinkend hervor.</p>',5),e("p",null,[e("video",{src:c,controls:"",playsinline:"",preload:"metadata"},[n(" Ihr Browser unterstützt das Abspielen von HTML5-Videos nicht. Sie können die Datei "),e("a",{href:"/videos/conduit_connection_map_find.webm",download:""},"herunterladen"),n(" anstelle des Videos. ")])],-1),r('<p>Um Liste und Karte abzugleichen, schalten Sie in der Legende die Beschriftungen des Layers „Trasse“ ein: Die Karte zeigt dann die Trassen-IDs an, die in der Liste stehen.</p><h3 id="_11-2-3-zuordnung-loschen" tabindex="-1">11.2.3 Zuordnung löschen <a class="header-anchor" href="#_11-2-3-zuordnung-loschen" aria-label="Permalink to &quot;11.2.3 Zuordnung löschen&quot;">​</a></h3><p>Über das Papierkorb-Symbol am rechten Rand einer Zeile heben Sie eine Zuordnung wieder auf. Gelöscht wird dabei nur die Verbindung zwischen Rohr und Trassensegment – beide selbst bleiben erhalten.</p><div class="danger custom-block"><p class="custom-block-title">Achtung</p><p>Das Löschen erfolgt ohne Rückfrage: Der Eintrag verschwindet mit dem Klick, und rückgängig machen lässt sich das nicht.</p></div><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Das Löschen setzt die Zugriffsstufe „Vollzugriff“ voraus; die Berechtigung zum Bearbeiten genügt dafür nicht. Fehlt sie, erscheint „Fehler beim Löschen der Trassenverbindung“, und die Zuordnung bleibt bestehen. Wenden Sie sich in diesem Fall an Ihre Administration.</p></div><h2 id="_11-3-routing-modus" tabindex="-1">11.3 Routing-Modus <a class="header-anchor" href="#_11-3-routing-modus" aria-label="Permalink to &quot;11.3 Routing-Modus&quot;">​</a></h2><p>Der <strong>Routing-Modus</strong> bestimmt, wie viele Trassensegmente ein Klick in die Karte zuordnet.</p><ul><li>Routing-Modus <strong>ausgeschaltet</strong>: Jeder Klick ordnet genau das angeklickte Trassensegment zu.</li><li>Routing-Modus <strong>eingeschaltet</strong>: Der erste Klick setzt den Start-, der zweite den Endpunkt. Qonnectra berechnet den kürzesten Weg zwischen beiden und ordnet alle Trassensegmente auf diesem Weg auf einmal zu.</li></ul><p><img src="'+g+'" alt="Screenshot Rohrzuordnung mit Hervorhebung des Umschalters „Routing-Modus“ oben im Arbeitsbereich" data-zoomable="true"></p>',9),e("p",null,[e("video",{src:m,controls:"",playsinline:"",preload:"metadata"},[n(" Ihr Browser unterstützt das Abspielen von HTML5-Videos nicht. Sie können die Datei "),e("a",{href:"/videos/conduit_connection_routing.webm",download:""},"herunterladen"),n(" anstelle des Videos. ")])],-1),r('<p>Ein dritter Klick verwirft die berechnete Route und setzt einen neuen Startpunkt; dasselbe bewirkt das Aus- und Wiedereinschalten des Routing-Modus. Verworfen wird dabei nur die Auswahl in der Karte – was bereits zugeordnet ist, bleibt in der Liste.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Start- und Endpunkt müssen im Trassennetz miteinander verbunden sein. Findet Qonnectra keinen Weg, meldet es „Fehler beim Berechnen der Route“, und es wird nichts zugeordnet.</p></div><h2 id="_11-4-routing-toleranz-richtig-wahlen" tabindex="-1">11.4 Routing-Toleranz richtig wählen <a class="header-anchor" href="#_11-4-routing-toleranz-richtig-wahlen" aria-label="Permalink to &quot;11.4 Routing-Toleranz richtig wählen&quot;">​</a></h2><p>Wie groß der Abstand zwischen zwei Segmenten sein darf, damit der Routing-Modus sie noch als verbunden ansieht, legt die „Routing-Toleranz“ unter „Einstellungen“ im Abschnitt „Rohrzuordnung“ fest, siehe Kapitel <a href="./17-einstellungen.html">Einstellungen</a>.</p><h2 id="_11-5-trassenverbindungen-anzeigen" tabindex="-1">11.5 Trassenverbindungen anzeigen <a class="header-anchor" href="#_11-5-trassenverbindungen-anzeigen" aria-label="Permalink to &quot;11.5 Trassenverbindungen anzeigen&quot;">​</a></h2><p>Der Umschalter „Trassenverbindungen anzeigen“ hebt die Trassensegmente, die dem ausgewählten Rohr bereits zugeordnet sind, in der Karte farbig hervor. So sehen Sie, welchen Weg das Rohr im Netz nimmt und an welcher Stelle noch eine Zuordnung fehlt.</p><p><img src="'+b+'" alt="Screenshot Rohrzuordnung mit Hervorhebung des Umschalters „Trassenverbindungen anzeigen“ oben im Arbeitsbereich und der hervorgehobenen Trassensegmente in der Kartenmitte" data-zoomable="true"></p><p>Ohne ausgewähltes Rohr bleibt der Umschalter wirkungslos.</p><h2 id="_11-6-nach-kennzeichen-eingrenzen" tabindex="-1">11.6 Nach Kennzeichen eingrenzen <a class="header-anchor" href="#_11-6-nach-kennzeichen-eingrenzen" aria-label="Permalink to &quot;11.6 Nach Kennzeichen eingrenzen&quot;">​</a></h2><p>Das Feld „Kennzeichen“ grenzt die Rohrauswahl auf ein Kennzeichen ein.</p><p><img src="'+p+'" alt="Screenshot Rohrzuordnung mit Hervorhebung der Projektauswahl in der Kopfzeile und des Feldes „Kennzeichen“ im Arbeitsbereich" data-zoomable="true"></p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Wechseln Sie das Kennzeichen, wird die Rohrauswahl zurückgesetzt. Gibt es zu Projekt und Kennzeichen kein Rohr, meldet das Feld „Keine Rohre gefunden“.</p></div>',12)])])}const K=t(_,[["render",z]]);export{v as __pageData,K as default};
